def parse(self, parser: "Parser") -> t.Union[nodes.Node, t.List[nodes.Node]]:
    def _validate_trans_variables(variables: t.Dict[str, nodes.Expr], parser: "Parser", lineno: int) -> None:
        for name, var in variables.items():
            if not name.isidentifier():
                parser.fail(f"Invalid variable name: {name}", lineno=lineno)
            if name in GETTEXT_FUNCTIONS:
                parser.fail(f"Variable name conflicts with translation function names: {name}", lineno=lineno)
            if isinstance(var, nodes.Call):
                _validate_trans_expression(name, var, parser, lineno=lineno)

    def _validate_trans_expression(name: str, expr: nodes.Expr, parser: "Parser", lineno: int) -> None:
        if isinstance(expr, nodes.Const) or isinstance(expr, nodes.Name) or isinstance(expr, nodes.Call) or isinstance(expr, nodes.Getattr) or isinstance(expr, nodes.Filter) or isinstance(expr, nodes.Test):
            return
        parser.fail(f"Invalid expression type: {expr!r}", lineno=lineno)

    _validate_trans_variables(self.variables, parser, parser.stream.current.lineno)
    return super().parse(parser)
```

